#include <devkit/gfx/camera.h>

inline const std::string g_vssource = R"(
		#version 330 core

		layout (location = 0) in vec3 Vertex;
		layout (location = 1) in vec3 normal;

		struct Camera {
			mat4 VP;
			vec3 position;
			vec3 direction;
		}; uniform Camera u_camera;

		out vec3 Position;
		out vec3 Normal;

		void main()
		{
			vec4 vM = vec4(Vertex.xyz, 1.0);

			gl_Position = vM * u_camera.VP;
			Position = vec3(vM.x / vM.w, vM.y / vM.w, vM.z / vM.w);
			Normal    = normal;
		})";

inline const std::string g_fssource = R"(
		#version 330 core

		struct Camera {
			mat4 VP;
			vec3 position;
			vec3 direction;
		}; uniform Camera u_camera;

		in vec3 Normal;
		in vec3 Position;

		out vec4 FragColor;

		void main()
		{
			float prod = 0.0;

			// PERSPECTIVE
			if (u_camera.VP[3][3] == 1.0) {
				prod = dot(normalize(-u_camera.direction), normalize(Normal));
			}
			// ORTHOGRAPHIC
			else {
				prod = dot(normalize(u_camera.position - Position), normalize(Normal));
			}
    
			if (prod < 0)
				prod *= -1;
			float diffuse = .45 + prod / 3;
			FragColor = vec4(diffuse, diffuse, diffuse, 1.f);
		})";

